// OMNICHANNEL NORMALIZER — turns ANY channel into one shape: { chatInput, channel, customer_id }
// Sources handled: web chat widget, Twilio Voice (SpeechResult), Twilio SMS (Body/From), email gateway (message/text)
const j = $input.first().json;

// Path 1: Chat widget (LangChain Chat Trigger)
if (j.chatInput !== undefined) {
  return [{ json: { chatInput: j.chatInput, channel: 'chat', customer_id: j.sessionId || 'chat-user' } }];
}

// Path 2: Webhook from a channel gateway (voice / sms / email)
const b = j.body || j;
let channel = b.channel;
if (!channel) {
  if (b.SpeechResult || b.CallSid) channel = 'voice';      // Twilio Voice <Gather input=speech>
  else if (b.Body || b.MessageSid) channel = 'sms';          // Twilio SMS / WhatsApp
  else channel = 'email';                                     // email-to-webhook gateway
}
return [{ json: {
  chatInput: b.message || b.SpeechResult || b.Body || b.text || '',
  channel: channel,
  customer_id: b.from || b.From || b.customer_id || b.email || 'unknown'
}}];

const t = String($fromAI('tracking_number','The DHL tracking number from the customer')).trim().replace(/\s+/g,'');
const db = {
 '1234567890':{status:'WITH DELIVERY COURIER',scan:'Out for delivery',loc:'Chennai Gateway, Tamil Nadu, IN',eta:'Today by 20:00',svc:'DHL Express Worldwide',from:'Mumbai, IN',to:'Chennai, IN',wt:'2.3 kg',last:'08:30 With delivery courier — vehicle TN-07-1123'},
 '9876543210':{status:'DELIVERED',scan:'Delivered - signed for',loc:'Andheri East, Mumbai, IN',eta:'Delivered 08 Jun 14:45',svc:'DHL eCommerce',from:'New Delhi, IN',to:'Mumbai, IN',wt:'0.8 kg',last:'14:45 Delivered, signed by P. SHARMA',pod:true},
 '1111222233':{status:'CUSTOMS STATUS UPDATED',scan:'Clearance processing — documents required',loc:'Delhi Customs, IGI Airport, IN',eta:'Held — 2-3 working days after clearance',svc:'DHL Express Worldwide',from:'Frankfurt, DE',to:'New Delhi, IN',wt:'5.1 kg',last:'09:00 On hold — commercial invoice required',incoterm:'DAP (receiver pays duty)'},
 '5555666677':{status:'SHIPMENT ON HOLD',scan:'Delay — adverse weather',loc:'Bengaluru Gateway, Karnataka, IN',eta:'Revised: 12 Jun',svc:'DHL Express Worldwide',from:'Hyderabad, IN',to:'Coimbatore, IN',wt:'1.4 kg',last:'16:00 Held — regional weather advisory'},
 '2222333344':{status:'IN TRANSIT',scan:'Departed DHL facility',loc:'Mumbai Gateway, IN',eta:'11 Jun by 18:00',svc:'DHL Express Worldwide',from:'Pune, IN',to:'Bengaluru, IN',wt:'3.2 kg',last:'23:20 Departed facility — Mumbai Gateway'},
 '3333444455':{status:'SHIPMENT PICKED UP',scan:'Collection booked',loc:'Hyderabad, IN (origin)',eta:'Est. delivery 13-14 Jun',svc:'DHL Express Worldwide',from:'Hyderabad, IN',to:'Chennai, IN',wt:'0.5 kg',last:'Pickup window 14:00-18:00 today'}
};
const r = db[t];
if(!r) return JSON.stringify({found:false,tracking_number:t,message:'No tracking data found. Ask the customer to verify the number from their DHL shipping confirmation (DHL Express waybills are 10 digits).'});
const out={found:true,tracking_number:t,status:r.status,latest_scan:r.scan,current_location:r.loc,estimated_delivery:r.eta,service:r.svc,origin:r.from,destination:r.to,weight:r.wt,last_event:r.last};
if(r.incoterm) out.incoterm=r.incoterm;
if(r.pod) out.pod_available=true;
return JSON.stringify(out);

const t = String($fromAI('tracking_number','Tracking number of a delivered shipment')).trim().replace(/\s+/g,'');
const pods = {
 '9876543210':{signatory:'P. SHARMA',delivered_at:'08 Jun 2025, 14:45',location:'Front desk / reception, Andheri East, Mumbai',pod_image:'https://dhl.com/pod/9876543210.pdf',geotag:'19.1136 N, 72.8697 E'}
};
const p = pods[t];
if(!p) return JSON.stringify({pod_available:false,tracking_number:t,message:'No POD available — this shipment is not marked Delivered yet, so there is no signature on file.'});
return JSON.stringify({pod_available:true,tracking_number:t,signed_by:p.signatory,delivered_at:p.delivered_at,delivery_location:p.location,pod_document:p.pod_image,gps_geotag:p.geotag,note:'If the customer does not recognise the signatory or location, open an investigation and route to the claims team.'});

const s = String($fromAI('status','The shipment status, e.g. CUSTOMS STATUS UPDATED, SHIPMENT ON HOLD, WITH DELIVERY COURIER')).toUpperCase();
const g = {
 'WITH DELIVERY COURIER':'Ensure someone is available at the address to receive and sign. No other action needed.',
 'DELIVERED':'If not physically received, check reception/neighbours and the POD location first; then we can investigate.',
 'CUSTOMS STATUS UPDATED':'Have your commercial invoice and ID ready. Customs may request duty payment. Submit any requested document fast to avoid delay.',
 'SHIPMENT ON HOLD':'No action needed. The delivery date auto-updates and you will be notified when it moves again.',
 'IN TRANSIT':'Moving normally. Check again near the ETA for delivery-day updates.',
 'SHIPMENT PICKED UP':'Keep the package labelled and ready; the agent will collect in the pickup window.'
};
return JSON.stringify({status:s,guidance:g[s]||'Shipment is progressing normally; no action needed right now.'});

const dest = String($fromAI('destination_country','Destination country'));
const wt = parseFloat($fromAI('weight_kg','Total chargeable weight in kg')||'1');
const days = parseInt($fromAI('days_required','Business days available for delivery')||'5');
const intl = !['India','IN','india'].includes(dest);
const s=[];
if(intl){
 if(days<=1) s.push({service:'DHL Express 9:00 / 12:00',transit:'Next possible day by 09:00 or 12:00',note:'Time-definite premium'});
 if(days<=3) s.push({service:'DHL Express Worldwide',transit:'1-3 business days',note:'Standard international express — most used'});
 if(days<=6) s.push({service:'DHL Economy Select',transit:'2-6 business days',note:'Deferred, lower cost for non-urgent'});
 if(wt>70) s.push({service:'DHL Global Forwarding',transit:'Air/ocean freight',note:'Heavy/bulk cargo — custom quote'});
 s.push({service:'DHL eCommerce',transit:'4-10 business days',note:'Lowest cost for e-commerce parcels'});
}else{
 s.push({service:'Blue Dart (DHL Group) Domestic Priority',transit:'1-2 business days',note:'DHL Group India domestic express'});
 s.push({service:'Blue Dart Surface',transit:'2-5 business days',note:'Cost-effective domestic'});
 s.push({service:'DHL eCommerce India',transit:'3-6 business days',note:'Parcel/e-commerce'});
}
return JSON.stringify({destination:dest,weight_kg:wt,days_available:days,recommended:s,top_pick:s[0],note:'For India domestic, DHL Group ships via Blue Dart. Final service depends on serviceability of the pincode.'});

const actual = parseFloat($fromAI('actual_weight_kg','Actual weight per shipment in kg')||'1');
const L = parseFloat($fromAI('length_cm','Length in cm per piece')||'0');
const W = parseFloat($fromAI('width_cm','Width in cm per piece')||'0');
const H = parseFloat($fromAI('height_cm','Height in cm per piece')||'0');
const pieces = parseInt($fromAI('pieces','Number of pieces')||'1');
const intl = String($fromAI('international','true if international else false')||'true')==='true';
// DHL volumetric weight formula: (L x W x H) / 5000 in cm, per piece
const volPerPiece = (L*W*H)/5000;
const volTotal = Math.round(volPerPiece*pieces*100)/100;
const chargeable = Math.max(actual, volTotal);
const basis = volTotal>actual ? 'VOLUMETRIC (dimensions exceed actual weight)' : 'ACTUAL weight';
let base = intl?30:6; let perKg = intl?6.5:2.5; const cur = intl?'USD':'INR'; const mult = intl?1:80;
const est = (base + perKg*chargeable)*mult;
const low = Math.round(est*0.85); const high = Math.round(est*1.3);
return JSON.stringify({actual_weight_kg:actual,volumetric_weight_kg:volTotal,chargeable_weight_kg:chargeable,charged_on:basis,currency:cur,estimate_range:cur+' '+low+' - '+high,important:'DHL bills on chargeable weight ('+chargeable+' kg here), not actual. Fuel surcharge, remote-area and duties (if DAP) are extra. Estimate only.'});

const pickup=String($fromAI('pickup_address','Full pickup address'));
const delivery=String($fromAI('delivery_address','Full delivery address'));
const wt=$fromAI('weight_kg','Actual total weight kg');
const pieces=$fromAI('pieces','Number of pieces');
const contents=String($fromAI('contents','Contents description'));
const svc=$fromAI('service','DHL service selected');
const email=$fromAI('receiver_email','Receiver email');
const account=String($fromAI('account_number','9-digit DHL account number for B2B, or PREPAID for cash')||'PREPAID');
const incoterm=String($fromAI('incoterm','DDP or DAP for international, or DOMESTIC')||'DOMESTIC');
// Restricted-items screen
const banned=['cash','currency','gold','silver','precious metal','weapon','gun','ammunition','narcotic','drug','perishable','loose lithium','lithium battery only'];
const c=contents.toLowerCase();
const hit=banned.find(b=>c.includes(b));
if(hit){return JSON.stringify({success:false,blocked:true,reason:'Contents appear to include a restricted/prohibited item ("'+hit+'"). This cannot be booked automatically. Route the customer to a DHL restricted-goods specialist.'});}
const ref='DHL-BK-'+Date.now().toString().slice(-8);
const tn=Math.floor(Math.random()*9000000000+1000000000).toString();
return JSON.stringify({success:true,booking_reference:ref,tracking_number:tn,service:svc,billing_account:account,incoterm:incoterm,pickup:pickup,delivery:delivery,pieces:pieces,actual_weight_kg:wt,contents:contents,pickup_window:'10:00-14:00 (book before 14:00 for same-day pickup)',next_steps:['Label emailed to '+email+' within 30 mins','Attach label before pickup','Track at dhl.com using '+tn]});

const tn=String($fromAI('tracking_number','Tracking number')||'UNKNOWN');
const type=String($fromAI('issue_type','damage or loss')||'damage').toLowerCase();
const desc=String($fromAI('description','What went wrong')||'');
const noticed=String($fromAI('date_noticed','When the issue was noticed')||'today');
const ref='DHL-CLAIM-'+Date.now().toString().slice(-7);
const team=type.includes('loss')?'Trace & Investigations Team':'Claims & Damage Team';
return JSON.stringify({claim_filed:true,claim_reference:ref,tracking_number:tn,issue_type:type,date_noticed:noticed,assigned_team:team,escalated_to_human:true,sla:'A specialist will contact you within 24 hours',customer_next_step: type.includes('damage')?'RETAIN the damaged item and all original packaging — do not discard. Have clear photos ready for the inspector.':'Our investigations team will open a trace and update you within 24 hours; keep your shipping documents handy.'});

const type=String($fromAI('issue_type','damage or loss')||'damage').toLowerCase();
const insured=String($fromAI('insurance_purchased','true if Shipment Value Protection was bought')||'false')==='true';
const base={damage:'Damage is assessed after inspection of the item and packaging. Without Shipment Value Protection, DHL standard liability is capped by international convention (broadly ~USD 20-25/kg for Express). With Shipment Value Protection, cover is up to the insured/declared value.',loss:'Confirmed loss is compensated based on declared/insured value if Shipment Value Protection was purchased; otherwise capped at standard liability by weight. A trace runs up to ~8 working days before loss is confirmed.'};
return JSON.stringify({issue_type:type,shipment_value_protection:insured,policy:base[type]||base.damage,important:'Final amount is decided by the human claims specialist after assessment. This is general policy guidance only.'});

const doc=String($fromAI('document','Document name or general')||'general').toLowerCase();
const reqs={
 'commercial invoice':'Must include: sender & receiver details, full item descriptions, quantities, unit values, total value, currency and HS codes. The single most-requested customs document.',
 'packing list':'Itemised list: descriptions, quantities, weights and dimensions per box.',
 'certificate of origin':'Issued and stamped by the Chamber of Commerce in the origin country. Determines preferential duty under trade agreements.',
 'import license / iec':'India importers need a valid Importer Exporter Code (IEC). For restricted goods, the relevant import licence number.',
 'kyc':'For India customs clearance, the receiver KYC (ID + address proof) is often required for personal imports.',
 'msds':'Material Safety Data Sheet for chemicals/dangerous goods, with hazard classifications.'
};
if(reqs[doc]) return JSON.stringify({document:doc,requirement:reqs[doc],submit_to:'Reply to your DHL customs email with the document attached (PDF/scan)',clears_in:'1-3 working days after we receive it',duty_note:'If the shipment is DAP, the receiver pays duty before release; if DDP, the sender has already covered it.'});
return JSON.stringify({document:'general',common_docs:Object.keys(reqs),note:'For most India imports: Commercial Invoice + receiver KYC + (for businesses) IEC. Tell me what the shipment is and I will confirm exactly what you need.',incoterm_reminder:'Clarify DDP vs DAP so the customer knows whether they owe duty.'});

const val=parseFloat($fromAI('declared_value','Assessable/declared value of goods')||'0');
const cur=String($fromAI('currency','Currency e.g. USD/INR')||'USD');
const bcdRate=parseFloat($fromAI('bcd_rate','Basic Customs Duty rate percent, default 10')||'10')/100;
const igstRate=parseFloat($fromAI('igst_rate','IGST rate percent, default 18')||'18')/100;
// India import duty stack
const bcd=val*bcdRate;
const sws=bcd*0.10; // Social Welfare Surcharge = 10% of BCD
const igstBase=val+bcd+sws;
const igst=igstBase*igstRate;
const total=bcd+sws+igst;
const r=n=>Math.round(n*100)/100;
return JSON.stringify({assessable_value:val,currency:cur,basic_customs_duty:r(bcd),social_welfare_surcharge:r(sws),igst:r(igst),total_import_charges:r(total),effective_rate_pct:r((total/val)*100),breakdown:'BCD '+(bcdRate*100)+'% + SWS 10% of BCD + IGST '+(igstRate*100)+'% on (value+BCD+SWS)',disclaimer:'Estimate only. Final duty is set by Indian customs based on the HS code classification and current tariff.'});

const tn=String($fromAI('tracking_number','Tracking number')||'UNKNOWN');
const date=String($fromAI('preferred_date','Preferred delivery date')||'next business day');
return JSON.stringify({rescheduled:true,tracking_number:tn,new_delivery_date:date,window:'09:00-18:00',confirmation:'Re-attempt booked for '+date+'. The customer will get an SMS on delivery day with a tighter time window.'});

const tn=String($fromAI('tracking_number','Tracking number')||'UNKNOWN');
const method=String($fromAI('method','hub_pickup, neighbour or address_change')||'hub_pickup').toLowerCase();
const details=String($fromAI('details','Neighbour name/flat or new full address if applicable')||'');
const out={tracking_number:tn,method:method};
if(method.includes('hub')||method.includes('service')){out.result='Redirected to the nearest DHL ServicePoint. Bring the tracking number and a photo ID. Held for 5 working days, then returned to sender.';}
else if(method.includes('neigh')){out.result='Authorised to leave with neighbour: '+details+'. Customer will be notified once delivered.';}
else{out.result='Delivery address updated to: '+details+'. Note: a change of city/country can affect transit time and any applicable duty.';}
return JSON.stringify(out);
